from fastapi import APIRouter
from pydantic import BaseModel
from pymongo.errors import DuplicateKeyError

from . import ledger
from .db import get_db

router = APIRouter()


class PaymentCallback(BaseModel):
    id: str
    customer_id: str
    amount: int


def store_payment(callback: PaymentCallback) -> bool:
    """Store the payment. Returns False if this event was already stored."""
    try:
        get_db().payments.insert_one(
            {
                "provider_event_id": callback.id,
                "customer_id": callback.customer_id,
                "amount": callback.amount,
            }
        )
    except DuplicateKeyError:
        return False
    return True


@router.post("/webhooks/provider")
def process_callback(callback: PaymentCallback) -> dict:
    is_new = store_payment(callback)
    if is_new or get_db().ledger.find_one({"event_id": callback.id}) is None:
        # Credit once; on a retry only if the earlier attempt never reached the ledger.
        ledger.credit(callback.customer_id, callback.amount, callback.id)
    return {"ok": True}

